    IF NEW.refund_status='SUCCESS' AND v_request_refunded + NEW.refund_amount > v_approved THEN RAISE EXCEPTION 'Refund exceeds approved amount' USING ERRCODE = '45000'; END IF;
    IF v_payment_id IS NOT NULL AND NEW.refund_status='SUCCESS' THEN
